import { defineStore } from "pinia";
import { applyFilter } from "@/assistant/filter";
import type { JsonValue } from "@/assistant/json";

const defaultInput = {
  sensor: "gps",
  time: 1351824120,
  data: [48.75608, 2.302038],
};

function tryParse(input: string) {
  try {
    return JSON.parse(input);
  } catch {
    return undefined;
  }
}

const sizeToCount = {
  1: 255,
  2: 65535,
  4: 4294967295,
};

type IntegerSize = 1 | 2 | 4;
type IoType =
  | "charPtr"
  | "charArray"
  | "arduinoString"
  | "stdString"
  | "arduinoStream"
  | "stdStream";

export const useSettingsStore = defineStore("settings", {
  state() {
    return {
      assumeConstKeys: true,
      assumeConstValues: false,
      cpu: "uno_r4_wifi",
      deduplicateKeys: true,
      deduplicateValues: true,
      filter: true,
      filterJson: "true",
      input: defaultInput,
      inputJson: JSON.stringify(defaultInput, null, 2),
      ioType: "arduinoStream" as IoType,
      mode: "deserialize",
      filterEnabled: false,
      useDouble: false,
      useLongLong: false,
      slotIdSize: 1,
      stringLengthSize: 1,
    };
  },
  actions: {
    setFilterJson(val: string) {
      this.filterJson = val;
      this.filter = tryParse(val);
    },
    setInputJson(val: string) {
      this.inputJson = val;
      this.input = tryParse(val);
    },
  },
  getters: {
    isSerializing(): boolean {
      return this.mode === "serialize";
    },
    isDeserializing(): boolean {
      return this.mode === "deserialize";
    },
    filteredInput(): JsonValue {
      if (this.isDeserializing && this.filterEnabled)
        return applyFilter(this.input, this.filter);
      return this.input;
    },
    ignoreKeys(): boolean {
      if (this.isSerializing) return this.assumeConstKeys;
      else return false;
    },
    ignoreValues(): boolean {
      if (this.isSerializing) return this.assumeConstValues;
      else return false;
    },
    ioTypeNames(): Record<string, string> {
      return {
        charPtr: this.isSerializing ? "char*" : "const char*",
        charArray: "char[N]",
        arduinoString: "String",
        stdString: "std::string",
        arduinoStream: "Stream",
        stdStream: this.isSerializing ? "std::ostream" : "std::istream",
      };
    },
    hasErrors() {
      return this.filteredInput === undefined;
    },
    maxSlotCount(): number {
      return sizeToCount[this.slotIdSize as IntegerSize];
    },
    maxStringLength(): number {
      return sizeToCount[this.stringLengthSize as IntegerSize];
    },
  },
});
